/*!40000 ALTER TABLE `admission_applicant` ENABLE KEYS */;
DROP TABLE IF EXISTS `admission_application`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `admission_application` (
  `version` bigint unsigned NOT NULL,
  `application_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `application_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `application_date` date NOT NULL,
  `application_status` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `eligibility_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `remarks` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `academic_year_id` smallint unsigned NOT NULL,
  `admission_applicant_id` bigint unsigned NOT NULL,
  `admission_category_id` smallint unsigned DEFAULT NULL,
  `admitted_student_id` bigint unsigned DEFAULT NULL,
  `created_by_id` bigint NOT NULL,
  `programme_id` smallint unsigned NOT NULL,
  `reviewer_id` bigint DEFAULT NULL,
  `specialization_id` smallint unsigned DEFAULT NULL,
  `updated_by_id` bigint NOT NULL,
  PRIMARY KEY (`application_id`),
  UNIQUE KEY `application_number` (`application_number`),
  UNIQUE KEY `uq_m6_application_student` (`application_id`,`admitted_student_id`),
  KEY `ix_m6_application_queue` (`programme_id`,`academic_year_id`,`application_status`,`application_id`),
  KEY `admission_applicatio_academic_year_id_20c68e69_fk_academic_` (`academic_year_id`),
  KEY `admission_applicatio_admission_applicant__3e33ec74_fk_admission` (`admission_applicant_id`),
  KEY `admission_applicatio_admission_category_i_56b579aa_fk_admission` (`admission_category_id`),
  KEY `admission_applicatio_admitted_student_id_f82b3882_fk_student_s` (`admitted_student_id`),
  KEY `admission_applicatio_created_by_id_03f64385_fk_user_acco` (`created_by_id`),
  KEY `admission_applicatio_reviewer_id_6f56baf0_fk_user_acco` (`reviewer_id`),
  KEY `admission_applicatio_updated_by_id_068234a8_fk_user_acco` (`updated_by_id`),
  KEY `fk_m6_application_specialization` (`specialization_id`,`programme_id`),
  CONSTRAINT `admission_applicatio_academic_year_id_20c68e69_fk_academic_` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_year` (`academic_year_id`),
  CONSTRAINT `admission_applicatio_admission_applicant__3e33ec74_fk_admission` FOREIGN KEY (`admission_applicant_id`) REFERENCES `admission_applicant` (`admission_applicant_id`),
  CONSTRAINT `admission_applicatio_admission_category_i_56b579aa_fk_admission` FOREIGN KEY (`admission_category_id`) REFERENCES `admission_category` (`admission_category_id`),
  CONSTRAINT `admission_applicatio_admitted_student_id_f82b3882_fk_student_s` FOREIGN KEY (`admitted_student_id`) REFERENCES `student` (`student_id`),
  CONSTRAINT `admission_applicatio_created_by_id_03f64385_fk_user_acco` FOREIGN KEY (`created_by_id`) REFERENCES `user_account` (`user_id`),
  CONSTRAINT `admission_applicatio_programme_id_15926ce0_fk_programme` FOREIGN KEY (`programme_id`) REFERENCES `programme` (`programme_id`),
  CONSTRAINT `admission_applicatio_reviewer_id_6f56baf0_fk_user_acco` FOREIGN KEY (`reviewer_id`) REFERENCES `user_account` (`user_id`),
  CONSTRAINT `admission_applicatio_specialization_id_8f770b23_fk_programme` FOREIGN KEY (`specialization_id`) REFERENCES `programme_specialization` (`specialization_id`),
  CONSTRAINT `admission_applicatio_updated_by_id_068234a8_fk_user_acco` FOREIGN KEY (`updated_by_id`) REFERENCES `user_account` (`user_id`),
  CONSTRAINT `fk_m6_application_specialization` FOREIGN KEY (`specialization_id`, `programme_id`) REFERENCES `programme_specialization` (`specialization_id`, `programme_id`),
  CONSTRAINT `admission_application_chk_1` CHECK ((`version` >= 0)),
  CONSTRAINT `chk_m6_application_conversion` CHECK ((((`admitted_student_id` is not null) and (`application_status` = _utf8mb4'ADMITTED')) or ((`application_status` <> _utf8mb4'ADMITTED') and (`admitted_student_id` is null)))),
  CONSTRAINT `chk_m6_application_eligible` CHECK (((`application_status` not in (_utf8mb4'ELIGIBLE',_utf8mb4'SELECTED',_utf8mb4'ADMITTED')) or (`eligibility_status` = _utf8mb4'ELIGIBLE')))
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
