INSERT INTO `announcement` VALUES (1,1,NULL,'Sample Holiday Notice','Sample holiday notice for all.','2026-01-05 09:00:00',NULL,'PENDING','ALL','2026-10-07 06:24:06',1),(2,1,NULL,'Semester registration opens','Students may register for the upcoming semester through the Registration module until the end of the month.','2026-10-04 08:25:38',NULL,'APPROVED','STUDENTS','2026-10-07 08:25:38',1),(3,1,NULL,'Faculty meeting - Friday 3 PM','All teaching staff are requested to attend the monthly faculty meeting in the main seminar hall.','2026-10-05 08:25:38',NULL,'APPROVED','STAFF','2026-10-07 08:25:38',1),(4,2,NULL,'Internal assessment schedule published','The IA-1 timetable is now available. Please check your department notice board and the calendar.','2026-10-06 08:25:38',NULL,'APPROVED','ALL','2026-10-07 08:25:38',1),(5,1,NULL,'Library hours extended during exams','The central library will remain open until 9 PM during the examination period.','2026-10-07 08:25:38',NULL,'APPROVED','ALL','2026-10-07 08:25:38',1),(6,3,NULL,'Annual sports meet - volunteers needed','Interested students may register with the sports committee by next Wednesday.','2026-10-07 08:25:38',NULL,'PENDING','STUDENTS','2026-10-07 08:25:38',1),(7,1,NULL,'Holiday on account of local festival','The campus will remain closed on the notified date. Regular schedules resume the next working day.','2026-10-08 08:25:38',NULL,'DRAFT','ALL','2026-10-07 08:25:38',1);
