  CONSTRAINT `platform_people_acco_user_id_755e34e6_fk_user_acco` FOREIGN KEY (`user_id`) REFERENCES `user_account` (`user_id`),
  CONSTRAINT `chk_people_link_root` CHECK ((((`employee_id` is null) and (`student_id` is not null)) or ((`employee_id` is not null) and (`student_id` is null))))
