CREATE TABLE `role_delegation` (
  `role_delegation_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `valid_from` datetime NOT NULL,
  `valid_to` datetime NOT NULL,
  `delegation_status` enum('PENDING','ACTIVE','REVOKED','EXPIRED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL,
  `approved_by_user_id` bigint DEFAULT NULL,
  `delegate_user_id` bigint NOT NULL,
  `delegator_user_id` bigint NOT NULL,
  `source_assignment_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`role_delegation_id`),
  KEY `role_delegation_approved_by_user_id_2c9d9527_fk_user_acco` (`approved_by_user_id`),
  KEY `role_delegation_delegate_user_id_91a72d25_fk_user_acco` (`delegate_user_id`),
  KEY `role_delegation_delegator_user_id_5c388ac6_fk_user_acco` (`delegator_user_id`),
  KEY `role_delegation_source_assignment_id_6349594e_fk_user_role` (`source_assignment_id`),
  CONSTRAINT `role_delegation_approved_by_user_id_2c9d9527_fk_user_acco` FOREIGN KEY (`approved_by_user_id`) REFERENCES `user_account` (`user_id`),
  CONSTRAINT `role_delegation_delegate_user_id_91a72d25_fk_user_acco` FOREIGN KEY (`delegate_user_id`) REFERENCES `user_account` (`user_id`),
  CONSTRAINT `role_delegation_delegator_user_id_5c388ac6_fk_user_acco` FOREIGN KEY (`delegator_user_id`) REFERENCES `user_account` (`user_id`),
  CONSTRAINT `role_delegation_source_assignment_id_6349594e_fk_user_role` FOREIGN KEY (`source_assignment_id`) REFERENCES `user_role_assignment` (`user_role_assignment_id`),
  CONSTRAINT `chk_role_delegation_dates` CHECK ((`valid_to` > `valid_from`)),
  CONSTRAINT `chk_role_delegation_users` CHECK ((`delegator_user_id` <> `delegate_user_id`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
