/*!40000 ALTER TABLE `student` ENABLE KEYS */;
DROP TABLE IF EXISTS `student_address`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_address` (
  `student_address_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `address_type` varchar(14) NOT NULL,
  `address_line_1` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `address_line_2` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `postal_code` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `valid_from` date DEFAULT NULL,
  `valid_to` date DEFAULT NULL,
  `is_primary` tinyint(1) NOT NULL DEFAULT '0',
  `current_primary_student_id` bigint unsigned GENERATED ALWAYS AS ((case when ((`is_primary` = 1) and (`valid_to` is null)) then `student_id` else NULL end)) STORED,
  `country_id` smallint unsigned NOT NULL,
  `state_id` smallint unsigned DEFAULT NULL,
  `student_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`student_address_id`),
  UNIQUE KEY `uq_student_current_primary_address` (`current_primary_student_id`),
  KEY `student_address_country_id_a87a8326_fk_country_country_id` (`country_id`),
  KEY `student_address_state_id_38507de9_fk_state_state_id` (`state_id`),
  KEY `student_address_student_id_724bd9a3_fk_student_student_id` (`student_id`),
  CONSTRAINT `student_address_country_id_a87a8326_fk_country_country_id` FOREIGN KEY (`country_id`) REFERENCES `country` (`country_id`),
  CONSTRAINT `student_address_state_id_38507de9_fk_state_state_id` FOREIGN KEY (`state_id`) REFERENCES `state` (`state_id`),
  CONSTRAINT `student_address_student_id_724bd9a3_fk_student_student_id` FOREIGN KEY (`student_id`) REFERENCES `student` (`student_id`),
  CONSTRAINT `chk_m5_student_address_address_type` CHECK ((`address_type` in (_utf8mb4'PERMANENT',_utf8mb4'CURRENT',_utf8mb4'CORRESPONDENCE',_utf8mb4'OTHER'))),
  CONSTRAINT `chk_m5_student_address_dates` CHECK (((`valid_from` is null) or (`valid_to` is null) or (`valid_to` >= `valid_from`)))
) ENGINE=InnoDB AUTO_INCREMENT=102 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

