CREATE TABLE `student_course_registration` (
  `version` bigint unsigned NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `course_registration_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `registration_type` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `registration_date` date NOT NULL,
  `registration_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `course_offering_id` bigint unsigned NOT NULL,
  `created_by_id` bigint NOT NULL,
  `programme_term_offering_id` bigint unsigned NOT NULL,
  `updated_by_id` bigint NOT NULL,
  `term_registration_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`course_registration_id`),
  UNIQUE KEY `uq_student_course_registration` (`term_registration_id`,`course_offering_id`),
  UNIQUE KEY `uq_course_registration_owner` (`course_registration_id`,`course_offering_id`),
  KEY `ix_m7_course_seats` (`course_offering_id`,`registration_status`),
  KEY `student_course_regis_created_by_id_039c949c_fk_user_acco` (`created_by_id`),
  KEY `student_course_regis_programme_term_offer_9f8bddd3_fk_programme` (`programme_term_offering_id`),
  KEY `student_course_regis_updated_by_id_21cce910_fk_user_acco` (`updated_by_id`),
  KEY `fk_m7_registration_term_owner` (`term_registration_id`,`programme_term_offering_id`),
  KEY `fk_m7_registration_offering_owner` (`course_offering_id`,`programme_term_offering_id`),
  CONSTRAINT `fk_m7_registration_offering_owner` FOREIGN KEY (`course_offering_id`, `programme_term_offering_id`) REFERENCES `course_offering` (`course_offering_id`, `programme_term_offering_id`),
  CONSTRAINT `fk_m7_registration_term_owner` FOREIGN KEY (`term_registration_id`, `programme_term_offering_id`) REFERENCES `student_term_registration` (`term_registration_id`, `programme_term_offering_id`),
  CONSTRAINT `student_course_regis_course_offering_id_efd16b14_fk_course_of` FOREIGN KEY (`course_offering_id`) REFERENCES `course_offering` (`course_offering_id`),
  CONSTRAINT `student_course_regis_created_by_id_039c949c_fk_user_acco` FOREIGN KEY (`created_by_id`) REFERENCES `user_account` (`user_id`),
  CONSTRAINT `student_course_regis_programme_term_offer_9f8bddd3_fk_programme` FOREIGN KEY (`programme_term_offering_id`) REFERENCES `programme_term_offering` (`programme_term_offering_id`),
  CONSTRAINT `student_course_regis_term_registration_id_c28aab85_fk_student_t` FOREIGN KEY (`term_registration_id`) REFERENCES `student_term_registration` (`term_registration_id`),
  CONSTRAINT `student_course_regis_updated_by_id_21cce910_fk_user_acco` FOREIGN KEY (`updated_by_id`) REFERENCES `user_account` (`user_id`),
  CONSTRAINT `chk_m7_registration_status` CHECK ((`registration_status` in (_utf8mb4'REGISTERED',_utf8mb4'APPROVED',_utf8mb4'DROPPED',_utf8mb4'WITHDRAWN',_utf8mb4'COMPLETED'))),
  CONSTRAINT `chk_m7_registration_type` CHECK ((`registration_type` in (_utf8mb4'REGULAR',_utf8mb4'ELECTIVE',_utf8mb4'BACKLOG',_utf8mb4'REPEAT',_utf8mb4'IMPROVEMENT',_utf8mb4'AUDIT',_utf8mb4'CREDIT_TRANSFER'))),
  CONSTRAINT `student_course_registration_chk_1` CHECK ((`version` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
