CREATE TABLE `student_previous_education` (
  `previous_education_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `qualification_level` varchar(7) NOT NULL,
  `examination_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `institution_name` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `board_university` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `registration_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `month_of_passing` tinyint unsigned DEFAULT NULL,
  `year_of_passing` year DEFAULT NULL,
  `result_class` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `marks_obtained` decimal(8,2) DEFAULT NULL,
  `maximum_marks` decimal(8,2) DEFAULT NULL,
  `percentage` decimal(5,2) DEFAULT NULL,
  `student_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`previous_education_id`),
  UNIQUE KEY `uq_previous_education` (`student_id`,`qualification_level`,`registration_number`),
  CONSTRAINT `student_previous_edu_student_id_a488864a_fk_student_s` FOREIGN KEY (`student_id`) REFERENCES `student` (`student_id`),
  CONSTRAINT `chk_m5_education_marks` CHECK (((`marks_obtained` is null) or (`maximum_marks` is null) or (`marks_obtained` <= `maximum_marks`))),
  CONSTRAINT `chk_m5_education_month` CHECK (((`month_of_passing` is null) or ((`month_of_passing` >= 1) and (`month_of_passing` <= 12)))),
  CONSTRAINT `chk_m5_education_percent` CHECK (((`percentage` is null) or ((`percentage` >= 0) and (`percentage` <= 100)))),
  CONSTRAINT `chk_m5_student_previou_marks_obtain` CHECK (((`marks_obtained` is null) or (`marks_obtained` >= 0))),
  CONSTRAINT `chk_m5_student_previou_maximum_mark` CHECK (((`maximum_marks` is null) or (`maximum_marks` >= 0))),
  CONSTRAINT `chk_m5_student_previous__qualification` CHECK ((`qualification_level` in (_utf8mb4'SSLC',_utf8mb4'PUC_I',_utf8mb4'PUC_II',_utf8mb4'DIPLOMA',_utf8mb4'UG',_utf8mb4'PG',_utf8mb4'OTHER'))),
  CONSTRAINT `student_previous_education_chk_1` CHECK ((`month_of_passing` >= 0)),
  CONSTRAINT `student_previous_education_chk_2` CHECK ((`year_of_passing` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
